import type { FullSchema, SystemColumns, TableName } from '../db';
/**
 * A match rule that identifies which row in the matcher table corresponds to the source record.
 * The source record's `sourceField` value is compared against the matcher table's `matcherField` value.
 *
 * Each match rule is its own `dl_definition_rel_match` record on the instance and must have its
 * own `$id` so the same sys_id is used across all build environments.
 *
 * @interface
 */
export type DataLookupMatchRule<S extends TableName = TableName, M extends TableName = TableName> = Now.Internal.WithID<{
    /** Field on the source table whose value is used to find a matching row in the matcher table. */
    sourceField: keyof FullSchema<S> | SystemColumns | (string & {});
    /** Field on the matcher table to compare against the source field value. */
    matcherField: keyof FullSchema<M> | SystemColumns | (string & {});
    /**
     * When `true`, requires an exact value match between source and matcher fields.
     * When `false` (default), allows fuzzy or range-based matching.
     */
    exactMatch?: boolean;
}>;
/**
 * A setter rule that defines which field value to copy from a matched matcher table row
 * back to the source record.
 *
 * Each set rule is its own `dl_definition_rel_set` record on the instance and must have its
 * own `$id` so the same sys_id is used across all build environments.
 *
 * @interface
 */
export type DataLookupSetRule<S extends TableName = TableName, M extends TableName = TableName> = Now.Internal.WithID<{
    /** Field on the source table that receives the looked-up value. */
    targetField: keyof FullSchema<S> | SystemColumns | (string & {});
    /** Field on the matcher table that provides the value to copy to the source record. */
    matcherField: keyof FullSchema<M> | SystemColumns | (string & {});
    /**
     * When `true`, overwrites the target field even if it already has a value.
     * When `false` (default), leaves the target field unchanged if it already has a value.
     */
    alwaysReplace?: boolean;
}>;
/**
 * Configuration for a Data Lookup Definition (`dl_definition`).
 *
 * A Data Lookup Definition automates field population on a source table by matching
 * source record field values against rows in a custom matcher table (which must extend
 * `dl_matcher`), then copying matched field values back to the source record.
 *
 * The lookup fires as a server-side business rule on insert and/or update, and optionally
 * client-side when watched fields change on the form.
 *
 * @interface
 *
 * @example
 * DataLookup({
 *     $id: Now.ID['assignment-lookup'],
 *     name: 'Assignment Lookup',
 *     sourceTable: 'incident',
 *     matcherTable: 'dl_u_assignment',
 *     runOnUpdate: true,
 *     matchRules: [
 *         { sourceField: 'category', matcherField: 'category' },
 *     ],
 *     setRules: [
 *         { targetField: 'assignment_group', matcherField: 'assignment_group' },
 *     ],
 * })
 */
export type DataLookupConfig<S extends TableName = TableName, M extends TableName = TableName> = Now.Internal.WithIdAndMetadata<{
    /** Unique name for this data lookup definition. Maximum 40 characters. */
    name: string;
    /**
     * The table on which this lookup fires — the table whose records receive the auto-populated values.
     * Can be any OOB or custom table (e.g., `'incident'`, `'change_request'`, `'x_myapp_orders'`).
     */
    sourceTable: S;
    /**
     * The matcher table that drives the lookup — must be a table that **extends `dl_matcher`**
     * in `sys_db_object`. Each row in this table defines a set of field values; when all match
     * rules pass for a source record, the matched row's values are copied to the source record.
     *
     * Custom matcher tables must extend `dl_matcher` (e.g., `'dl_u_assignment'`, `'dl_u_priority'`).
     * The build will succeed if you provide an incorrect table, but the lookup will not fire on the
     * instance — verify the table hierarchy in `sys_db_object` before deploying.
     */
    matcherTable: M;
    /**
     * When `false`, disables this definition and all its associated rules.
     * Defaults to `true`.
     */
    active?: boolean;
    /**
     * When `true`, fires this lookup as a server-side business rule on record insert.
     * Defaults to `true`.
     */
    runOnInsert?: boolean;
    /**
     * When `true`, fires this lookup as a server-side business rule on record update.
     * Defaults to `false` — must be explicitly enabled to fire on updates.
     */
    runOnUpdate?: boolean;
    /**
     * When `true`, re-runs the lookup client-side whenever any `matchRules` source field
     * changes on a form. Defaults to `true`.
     */
    runOnFormChange?: boolean;
    /**
     * Field pairs that determine which rows in the matcher table match the source record.
     * Each rule compares a source table field value against the corresponding matcher table field.
     */
    matchRules?: DataLookupMatchRule<S, M>[];
    /**
     * Field pairs that define which matcher table field values are copied back to the source record
     * when a matching row is found.
     */
    setRules?: DataLookupSetRule<S, M>[];
}>;
export declare function DataLookup<const S extends TableName, const M extends TableName>(config: DataLookupConfig<S, M>): DataLookupConfig<S, M>;
